        const A_shape = [_]usize{ input_dim, input_dim };
        const G_shape = [_]usize{ output_dim, output_dim };

        var A = try Tensor.eye(allocator, &A_shape);
        errdefer A.deinit();

        var G = try Tensor.eye(allocator, &G_shape);
        errdefer G.deinit();

        return KFACBlock{
            .A_inv = A,
            .G_inv = G,
            .damping = damping,
            .alpha = alpha,
            .update_freq = 10,
            .last_update = 0,
            .allocator = allocator,
        };
    }

